void dei_sc_delete( void )
{           
    CRITICAL ; 

    C_ENTER ;
    {
        UInt8 i ;

        for( i = 0 ; i < DEI_RF_ID_COUNT ; i ++ )
        {
            dei_sc.remote[i].sn  = 0 ; 
            dei_sc.remote[i].key = 0 ; 

        }

        dei_sc.car_sn = 0 ; 
        dei_sc.index  = 0 ;                 
    }
    C_LEAVE ;

}

//--------------------------------------------------------------------------//

void dei_sc_delete_enter( void )
{           
    dei_sc_ngrf_mode = DEI_SC_NGRF_MODE_ERASE;	
    dei_sc_tx(DEI_SC_ACK_MODE_CONFIGURATION,DEI_SC_NORMAL_TX,1000);
}

//--------------------------------------------------------------------------//

